    h, w = len(grid), len(grid[0])

    # Locate the compact rectangular striped object (the frame with a
    # differently colored horizontal band inside).
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and grid[a][b] != 0 and (a, b) not in seen:
                        seen.add((a, b))
                        stack.append((a, b))
            rs = [x for x, y in comp]
            cs = [y for x, y in comp]
            comps.append((min(rs), max(rs), min(cs), max(cs), comp))

    # Choose the smallest component with a horizontal interior stripe.
    choices = []
    for r0, r1, c0, c1, comp in comps:
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        for r in range(r0 + 1, r1):
            vals = [grid[r][c] for c in range(c0 + 1, c1)]
            if vals and len(set(vals)) == 1 and vals[0] != 0:
